<template>
  <div class="space-y-6">
    <PageHeader :title="editingId ? '编辑策略' : '创建策略'" parent="分流" description="保存为业务草稿，节点运行策略需通过配置版本发布。"><template #actions><router-link to="/routing/rules" class="ios-btn-secondary">返回策略</router-link></template></PageHeader>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="loading" />
    <form v-else @submit.prevent="save" class="space-y-6">
      <section class="panel-card p-6"><h2 class="font-semibold mb-4">基础信息</h2><div class="grid md:grid-cols-2 gap-4"><label class="text-sm">名称<input v-model="form.name" required maxlength="80" class="form-input-base mt-2" /></label><label class="text-sm">优先级<input v-model.number="form.priority" type="number" min="0" max="1000000" required class="form-input-base mt-2" /></label></div><label class="block text-sm mt-4"><input v-model="form.enabled" type="checkbox" /> 启用</label></section>
      <section class="panel-card p-6"><h2 class="font-semibold mb-4">生效范围</h2><p class="text-xs text-gray-500 mb-4">每一类未选择时表示全部；不同类别共同约束请求。</p><div class="grid md:grid-cols-2 gap-6">
        <fieldset><legend class="text-sm font-medium mb-2">用户</legend><label v-for="user in users" :key="user.id" class="block text-sm mb-2"><input v-model="form.scope.user_ids" type="checkbox" :value="user.id" /> {{ user.username }}</label></fieldset>
        <fieldset><legend class="text-sm font-medium mb-2">设备</legend><label v-for="device in devices.filter(item => !form.scope.user_ids?.length || form.scope.user_ids.includes(item.userId))" :key="device.id" class="block text-sm mb-2"><input v-model="form.scope.device_ids" type="checkbox" :value="device.id" /> {{ device.name }}</label></fieldset>
        <fieldset><legend class="text-sm font-medium mb-2">入口节点</legend><label v-for="node in nodes" :key="node.id" class="block text-sm mb-2"><input v-model="form.scope.node_ids" type="checkbox" :value="node.id" /> {{ node.name }}</label></fieldset>
        <fieldset><legend class="text-sm font-medium mb-2">入口节点组</legend><label v-for="group in groups" :key="group.id" class="block text-sm mb-2"><input v-model="form.scope.group_ids" type="checkbox" :value="group.id" /> {{ group.name }}</label></fieldset>
      </div></section>
      <section class="panel-card p-6"><h2 class="font-semibold mb-4">地址与服务匹配</h2><p class="text-xs text-gray-500 mb-4">域名、后缀、服务集合和 IP/CIDR 作为地址备选条件；任一命中即可。请输入主机名，不包含 URL 路径。IP / CIDR 只匹配字面 IP 地址，系统不做 DNS 解析，也不会把域名解析成 IP 后再匹配。</p><div class="grid md:grid-cols-2 gap-4">
        <label class="text-sm">精确 / 通配域名（每行一个）<textarea v-model="domainsText" rows="4" placeholder="api.example.com&#10;*.blocked.example" class="form-input-base mt-2 font-mono text-xs"></textarea></label><label class="text-sm">域名后缀（每行一个）<textarea v-model="suffixesText" rows="4" placeholder="example.com" class="form-input-base mt-2 font-mono text-xs"></textarea></label><label class="text-sm">IP / CIDR（每行一个）<textarea v-model="cidrsText" rows="3" placeholder="192.0.2.0/24" class="form-input-base mt-2 font-mono text-xs"></textarea><span class="block text-xs text-gray-500 mt-1">只匹配字面 IP / CIDR（如 192.0.2.0/24、2001:db8::/32）；不做 DNS 解析，域名请写在上面的域名或后缀里。</span></label>
        <fieldset><legend class="text-sm mb-2">服务规则</legend><label v-for="service in services" :key="service.id" class="block text-sm mb-2"><input v-model="form.match.service_ids" type="checkbox" :value="service.id" /> {{ service.name }}{{ service.enabled ? '' : '（草稿已禁用）' }}</label></fieldset>
      </div></section>
      <section class="panel-card p-6"><h2 class="font-semibold mb-4">端口、网络与时间</h2><div class="grid md:grid-cols-2 gap-4"><label class="text-sm">端口或范围（逗号分隔）<input v-model="portsText" placeholder="80,443,8000-9000" class="form-input-base mt-2" /></label><label class="text-sm">网络<select v-model="form.match.network" class="form-input-base mt-2"><option value="all">TCP + UDP</option><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label class="text-sm">生效时间段（空白表示全天）<input v-model="form.match.time_range" placeholder="23:00-06:00" class="form-input-base mt-2" /></label><label class="text-sm">时间段时区<input v-model="form.timezone" placeholder="Asia/Shanghai" class="form-input-base mt-2" /></label></div><p class="text-xs text-gray-500 mt-3">开始包含、结束不包含；跨午夜时间段可用。Agent 根据已发布版本定时协调，不依赖中央在线。</p><p v-if="form.match.network !== 'tcp' && (form.scope.user_ids?.length || form.scope.device_ids?.length)" class="text-xs text-amber-700 mt-3">当前 Xray 的 SOCKS5 UDP 不携带账户身份，涉及该入站的用户/设备 UDP 策略会被拒绝发布。请使用可执行该范围的协议或核心。</p></section>
      <section class="panel-card p-6"><h2 class="font-semibold mb-4">动作</h2><div class="grid md:grid-cols-2 gap-4"><label class="text-sm">执行动作<select v-model="form.action.type" class="form-input-base mt-2"><option value="Block">Block 阻断</option><option value="Direct">Direct 直连 / 允许</option><option value="Outbound">指定出站</option><option value="OutboundGroup">指定出口组</option><option value="ProxyChain">指定代理链</option></select></label><label v-if="form.action.type === 'Outbound'" class="text-sm">目标出站<select v-model="form.action.target_id" class="form-input-base mt-2"><option value="">请选择</option><option v-for="outbound in outbounds.filter(item => item.enabled)" :key="outbound.id" :value="outbound.id">{{ outbound.name }} · {{ nodes.find(node => node.id === outbound.nodeId)?.name }}</option></select></label><label v-if="form.action.type === 'OutboundGroup'" class="text-sm">目标出口组<select v-model="form.action.target_id" class="form-input-base mt-2"><option value="">请选择</option><option v-for="group in outboundGroups.filter(item => item.enabled)" :key="group.id" :value="group.id">{{ group.name }} · {{ nodes.find(node => node.id === group.nodeId)?.name }}</option></select></label><label v-if="form.action.type === 'ProxyChain'" class="text-sm">目标代理链<select v-model="form.action.target_id" class="form-input-base mt-2"><option value="">请选择</option><option v-for="chain in chains.filter(item => item.enabled)" :key="chain.id" :value="chain.id">{{ chain.name }} · {{ chain.nodeIds.length }} 节点</option></select></label></div><p class="text-xs text-gray-500 mt-3">指定出站策略适用于该出站所属节点；未选择入口节点时会自动限定到所属节点。失败处理由本策略独立设置，默认 Block，不继承目标自身的 Direct。</p></section>
      <section v-if="!['Direct','Block'].includes(form.action.type)" class="panel-card p-6 space-y-4"><h2 class="font-semibold">失败处理</h2><label class="block text-sm">目标不可用时<select v-model="form.action.failover" class="form-input-base mt-2"><option v-for="mode in ['Block','Direct','BackupOutbound','BackupOutboundGroup','BackupProxyChain']" :key="mode" :value="mode">{{ failureNames[mode] }}</option></select></label><label v-if="form.action.failover?.startsWith('Backup')" class="block text-sm">备用目标<select v-model="form.action.backup_id" class="form-input-base mt-2"><option value="">请选择</option><option v-for="backup in backupOptions" :key="backup.id" :value="backup.id">{{ backup.name }}</option></select></label><p v-if="form.action.failover === 'Direct'" class="text-xs text-amber-700">目标不可用时将从入口直连；固定出口场景建议使用阻断或备用出口。</p></section><section class="panel-card p-6"><h2 class="font-semibold mb-4">记录与备注</h2><div class="flex flex-wrap gap-4 text-sm"><label><input v-model="form.logging.log_domain" type="checkbox" /> 记录域名</label><label><input v-model="form.logging.log_traffic" type="checkbox" /> 记录流量</label><label><input v-model="form.logging.alert_on_block" type="checkbox" /> 阻断告警</label></div><label class="block text-sm mt-4">备注<textarea v-model="form.remark" maxlength="300" rows="3" class="form-input-base mt-2"></textarea></label><p class="text-xs text-gray-500 mt-3">仅记录域名级结果，不采集正文、完整 URL、Cookie 或密码。实际采集能力在访问记录模块继续接入。</p></section>
      <div class="flex justify-end gap-3"><router-link to="/routing/rules" class="ios-btn-secondary">取消</router-link><button :disabled="saving" class="ios-btn-primary disabled:opacity-40">{{ saving ? '保存中…' : '保存策略草稿' }}</button></div>
    </form>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, computed, onMounted } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { policyAPI, defaults, input, type PolicyInput, type ServiceSet } from '../api'; import { request, type Page } from '../../../app/apiClient'; import { authState } from '../../../app/auth'; import { showToast } from '../../../app/api'; import { userAPI, type ProxyUser, type ProxyDevice } from '../../users/api'; import { groupAPI, type NodeGroup } from '../../nodes/groupsApi'; import { type NodeView } from '../../nodes/api'; import { proxyAPI, type Outbound, type OutboundGroup, type ProxyChain, choices, failureNames } from '../../proxy/api'; import PageHeader from '../../../components/PageHeader.vue'; import ErrorState from '../../../components/ErrorState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue';
const outboundGroups = ref<OutboundGroup[]>([]); const chains = ref<ProxyChain[]>([]); const targetOwner = computed(() => form.action.type === 'Outbound' ? outbounds.value.find(item => item.id === form.action.target_id)?.nodeId : form.action.type === 'OutboundGroup' ? outboundGroups.value.find(item => item.id === form.action.target_id)?.nodeId : chains.value.find(item => item.id === form.action.target_id)?.nodeIds[0]); const backupOptions = computed(() => form.action.failover === 'BackupOutboundGroup' ? outboundGroups.value.filter(item => item.enabled && item.nodeId === targetOwner.value) : form.action.failover === 'BackupProxyChain' ? chains.value.filter(item => item.enabled && item.nodeIds[0] === targetOwner.value) : outbounds.value.filter(item => item.enabled && item.nodeId === targetOwner.value)); const route = useRoute(); const router = useRouter(); const editingId = computed(() => typeof route.params.id === 'string' ? route.params.id : '');
const form = reactive<PolicyInput>(defaults()); const domainsText = ref(''); const suffixesText = ref(''); const cidrsText = ref(''); const portsText = ref(''); const users = ref<ProxyUser[]>([]); const devices = ref<ProxyDevice[]>([]); const nodes = ref<NodeView[]>([]); const groups = ref<NodeGroup[]>([]); const services = ref<ServiceSet[]>([]); const outbounds = ref<Outbound[]>([]); const loading = ref(false); const saving = ref(false); const error = ref('');
async function load() { loading.value = true; try { const [u, d, n, g, s, o, og, pc] = await Promise.all([userAPI.list(1, '', 100), userAPI.devices('', 1, 100), request<Page<NodeView>>('/nodes?page=1&pageSize=100'), groupAPI.list(1, 100), policyAPI.services(1, 100), proxyAPI.outbounds('', 1, 100), choices((p,s) => proxyAPI.groups('',p,s)), choices((p,s) => proxyAPI.chains('',p,s))]); users.value = u.items; devices.value = d.items; nodes.value = n.items; groups.value = g.items; services.value = s.items; outbounds.value = o.items; outboundGroups.value = og; chains.value = pc; if (editingId.value) Object.assign(form, input(await policyAPI.get(editingId.value))); else { Object.assign(form, defaults()); form.timezone = authState.timezone; } domainsText.value = form.match.domains?.join('\n') || ''; suffixesText.value = form.match.suffixes?.join('\n') || ''; cidrsText.value = form.match.cidrs?.join('\n') || ''; portsText.value = form.match.ports?.join(',') || ''; error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
function lines(value: string) { return value.split('\n').map(item => item.trim()).filter(Boolean); }
async function save() { if (saving.value) return; saving.value = true; try { const value: PolicyInput = JSON.parse(JSON.stringify(form)); value.match.domains = lines(domainsText.value); value.match.suffixes = lines(suffixesText.value); value.match.cidrs = lines(cidrsText.value); value.match.ports = portsText.value.split(',').map(item => item.trim()).filter(Boolean); if (value.action.type === 'Direct' || value.action.type === 'Block') { value.action.failover = 'Block'; value.action.backup_id = ''; } if (value.action.type === 'Direct' || value.action.type === 'Block') value.action.target_id = ''; await policyAPI.save(editingId.value || null, value); showToast('策略草稿已保存，请生成并发布节点配置'); await router.push('/routing/rules'); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
onMounted(load);
</script>


